def group_tuples(Input):
    if not Input:
        return None
    # Filter out empty tuples to avoid index errors
    filtered = [t for t in Input if t]
    if not filtered:
        return None
    first_elements = [t[0] for t in filtered]
    count = Counter(first_elements)
    # Find first element that appears more than once (is common)
    commons = [elem for elem, c in count.items() if c > 1]
    if commons:
        # Return the one that appears earliest in the original order
        for elem in first_elements:
            if elem in commons:
                return elem
    # If no element appears more than once, return the first first-element
    return first_elements[0]

