    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(a)

    max_kadane = kadane(a)

    if k == 1:
        return max_kadane

    # Compute max prefix sum
    max_prefix = current = a[0]
    for x in a[1:]:
        current += x
        if current > max_prefix:
            max_prefix = current

    # Compute max suffix sum
    max_suffix = current = a[-1]
    for x in reversed(a[:-1]):
        current += x
        if current > max_suffix:
            max_suffix = current

    # Max subarray sum for two concatenated arrays
    double_arr = a * 2
    max_double = kadane(double_arr)

    if total_sum > 0:
        # max is either within two arrays or across multiple arrays including middle repetitions
