def group_tuples(Input):
    if not Input:
        return []
    # Only consider tuples with at least one element
    tuples_with_first = [t for t in Input if len(t) > 0]
    if not tuples_with_first:
        return []
    first_elements = [t[0] for t in tuples_with_first]
    count = Counter(first_elements)
    max_count = max(count.values())
    # Find all elements with maximum frequency
    max_elements = {elem for elem, c in count.items() if c == max_count}
    # Choose the earliest occurring element among them
    for t in tuples_with_first:
        if t[0] in max_elements:
            chosen = t[0]
            break
    return [t for t in tuples_with_first if t[0] == chosen]

